-- Contenido propio del Tema 7 (Entorno profesional).
-- Redactado a partir de docs/fuentes/enaire/t7.pdf (ENAIRE). reviewed=false: pendiente de revisión humana.

insert into public.topic_sections (id, topic_id, sort, title, body_md, source_pages, reviewed) values
  ('10000007-0000-4000-8001-000000000001', '00000000-0000-4000-8000-000000006007', 1, 'ENAIRE: naturaleza y origen', '**Qué es.** Entidad pública empresarial adscrita al **Ministerio de Transportes y Movilidad Sostenible**. Es el **gestor nacional de navegación aérea** en España.
- Origen: **Aena EPE**, creada por el **art. 82 de la Ley 4/1990 (29 de junio)**, de Presupuestos Generales del Estado para 1990.
- Pasó a denominarse **ENAIRE** por la **Ley 18/2014 (15 de octubre)**.
- Plan estratégico 2021-2025: **Plan de Vuelo 2025**, hoja de ruta de la transformación.', 'pp. 3-4', false),
  ('10000007-0000-4000-8001-000000000002', '00000000-0000-4000-8000-000000006007', 2, 'ENAIRE: cifras y funciones', '**Cifras clave**
- **5 centros de control** y **21 torres**.
- Más de **2 millones de vuelos** al año; en 2023 transportaron a más de **328 millones** de personas.
- Espacio aéreo gestionado: **2.190.000 km²**.
- Principal proveedor de servicios de navegación aérea e información aeronáutica en España, **4.º de Europa** por volumen de tráfico.

**Encomienda legal:** planificación, dirección, coordinación, explotación, conservación y administración del tráfico aéreo, de las telecomunicaciones e información aeronáutica y de las infraestructuras y redes del sistema. El servicio debe ser **seguro, eficaz, continuado y sostenible**.', 'pp. 4-5', false),
  ('10000007-0000-4000-8001-000000000003', '00000000-0000-4000-8000-000000006007', 3, 'ENAIRE: servicios ATS prestados y designaciones', '**Servicios de tránsito aéreo prestados:** control de área, aproximación y aeródromo, más información de vuelo, alerta y asesoramiento.
- Proveedor de **CNS** en todo el espacio aéreo español y en los aeropuertos de la red Aena.
- Designada **Operador de Infraestructuras Críticas (2015)** y **Operador de Servicios Esenciales (2019)**.', 'pp. 4-5', false),
  ('10000007-0000-4000-8001-000000000004', '00000000-0000-4000-8000-000000006007', 4, 'Grupo empresarial', 'ENAIRE constituye un grupo cuya actividad central es la gestión de la navegación aérea.
| Participada | Porcentaje |
|---|---|
| **Aena S.A.** (gestor aeroportuario) | **51 %** (accionista mayoritario) |
| **CRIDA** | 66,66 % |
| **STARTICAL** | 50 % |
| **Ineco** | 45,85 % |
| **Grupo EAD** | 36 % |

La **Fundación ENAIRE** gestiona y difunde el patrimonio artístico y fomenta la cultura aeronáutica.', 'p. 7', false),
  ('10000007-0000-4000-8001-000000000005', '00000000-0000-4000-8000-000000006007', 5, 'Equipo humano', 'Plantilla: más de **4.200 personas** (datos a 31 de octubre de 2024).

**Dos convenios colectivos**
- **III Convenio Colectivo profesional de Controladores de Tránsito Aéreo.**
- **I Convenio Colectivo del Grupo Aena** (personal no controlador).

**Plantilla por ocupaciones**
| Ocupación | Peso aprox. |
|---|---|
| Controladores aéreos | **49 %** |
| Gestión (administración, ambos convenios) | 26 % |
| Ingeniería y explotación técnica | 20 % |
| Operaciones (AIS, planes de vuelo, apoyo ATS) | 5 % |', 'p. 8', false),
  ('10000007-0000-4000-8001-000000000006', '00000000-0000-4000-8000-000000006007', 6, 'Plan de Vuelo 2025: propósito, misión y visión', '- **Propósito:** cuidar del vuelo para que sea **seguro, rápido, eficiente y sostenible**.
- **Misión:** servicios de navegación aérea con **seguridad, calidad, eficiencia y respeto al medioambiente**, contribuyendo al desarrollo económico y social de España.
- **Visión:** ser un **operador global, líder del sector**, basado en **las personas, la innovación y la digitalización**.', 'p. 10', false),
  ('10000007-0000-4000-8001-000000000007', '00000000-0000-4000-8000-000000006007', 7, 'Plan de Vuelo 2025: objetivos estratégicos', '- **1.** Reforzar la **seguridad** (cultura de seguridad, factor humano, ciberseguridad).
- **2.** Mejorar **calidad, escalabilidad y resiliencia** de los servicios (digitalización, modernización del espacio aéreo).
- **3.** Contribuir a la **movilidad sostenible** y la descarbonización.
- **4.** **Desarrollo de negocio e internacionalización.**
- **5.** Asegurar la **recuperación económica y viabilidad** de ENAIRE y aumentar su eficiencia y competitividad.
- **6.** Acelerar la **transformación cultural y organizativa** y la modernización.', 'pp. 10-11', false),
  ('10000007-0000-4000-8001-000000000008', '00000000-0000-4000-8000-000000006007', 8, 'Cielo Único Europeo (SES)', '- Iniciativa de la **Comisión Europea de 1999**.
- Objetivo: aumentar la eficiencia de la gestión del tránsito aéreo y de los servicios de navegación aérea.
  - Mejorar **capacidad, seguridad, coste-eficiencia y medio ambiente**.
  - **Reducir la fragmentación** del espacio aéreo europeo.
- Paquetes: **SES I (2004)**, **SES II (2009)**. **SES2+** se retomó a finales de 2020 y está en negociación (trílogos Comisión, Consejo y Parlamento).

**Sistema de rendimientos**
- Metas en **4 áreas:** seguridad, coste-eficiencia, capacidad y medioambiente, con incentivos y penalizaciones.
- Períodos de **5 años** (el primero duró 3). El período indicado va de **2020 a 2024**; **RP4 = 2025-2029**.', 'pp. 11-12', false),
  ('10000007-0000-4000-8001-000000000009', '00000000-0000-4000-8000-000000006007', 9, 'Servicios de navegación aérea certificados', 'ENAIRE está **certificada** según la normativa de la UE para:
- **ATS:** previene colisiones, acelera y ordena el tránsito, da asesoramiento e información y notifica y auxilia en alerta y salvamento.
- **CNS:** disponibilidad, explotación y mantenimiento de los medios técnicos del sistema.
- **AIS:** información relevante para planificar operaciones, actualizada y con calidad.
- **ATFM:** regularidad de los vuelos y capacidad del espacio aéreo.
- **ASM local (táctico, nivel 3):** coordinación civil/militar.
- **FPD:** diseño de procedimientos de vuelo.', 'pp. 12-13', false),
  ('10000007-0000-4000-8001-000000000010', '00000000-0000-4000-8000-000000006007', 10, 'Formación en ENAIRE', '**Formación de controladores**
- **Formación de unidad** (para ejercer las atribuciones de la licencia en la unidad), en 3 partes: **transición** (teoría), **Pre-OJT** (simulador) y **OJT** (puesto de trabajo).
- **Formación continua:** **actualización** (mantener la anotación de unidad: procedimientos, emergencias, PCATS, factores humanos) y **conversión** (cambios operativos de la unidad).
- Carrera profesional: instructores, evaluadores, supervisores, gestión y libre designación.
- Lingüística (inglés) y otra (PRL, seguridad, ofimática...).

**Máster en Gestión de Servicios de Navegación Aérea**
- ENAIRE con la **Universidad Politécnica y la Autónoma de Madrid**, en colaboración con la **OACI**.
- Certificación **TRAINAIR PLUS** de OACI.
- Dirigido a profesionales de ENAIRE, proveedores internacionales y otras organizaciones del sector.', 'pp. 14-15', false)
on conflict (id) do nothing;

insert into public.questions (id, topic_id, stem, options, correct_index, explanation, source_pages, difficulty, reviewed) values
  ('10000007-0000-4000-8002-000000000001', '00000000-0000-4000-8000-000000006007', '¿A qué ministerio está adscrita ENAIRE?', '["Ministerio de Defensa", "Ministerio de Transportes y Movilidad Sostenible", "Ministerio de Hacienda", "Ministerio de Industria y Turismo"]'::jsonb, 1, 'ENAIRE es una entidad pública empresarial adscrita al Ministerio de Transportes y Movilidad Sostenible (p. 4).', 'p. 4', 1, false),
  ('10000007-0000-4000-8002-000000000002', '00000000-0000-4000-8000-000000006007', '¿Qué norma cambió la denominación de Aena EPE por ENAIRE?', '["La Ley 4/1990, de 29 de junio", "El Convenio de Chicago de 1944", "El Reglamento europeo SES I de 2004", "La Ley 18/2014, de 15 de octubre"]'::jsonb, 3, 'Aena EPE pasó a denominarse ENAIRE por la Ley 18/2014 de 15 de octubre. La Ley 4/1990 fue la que creó Aena EPE (p. 3).', 'p. 3', 2, false),
  ('10000007-0000-4000-8002-000000000003', '00000000-0000-4000-8000-000000006007', '¿Por qué norma fue creada la entidad Aena EPE?', '["Por el art. 82 de la Ley 4/1990, de Presupuestos Generales del Estado para 1990", "Por la Ley 18/2014, de medidas urgentes para el crecimiento", "Por el Reglamento SES II de 2009", "Por un acuerdo de la Comisión Europea de 1999"]'::jsonb, 0, 'Aena EPE se creó por el artículo 82 de la Ley 4/1990 de 29 de junio, de Presupuestos Generales del Estado para 1990 (p. 3).', 'p. 3', 3, false),
  ('10000007-0000-4000-8002-000000000004', '00000000-0000-4000-8000-000000006007', '¿Cuántos centros de control y torres opera ENAIRE según el tema?', '["Cuatro centros de control y 21 torres", "Cinco centros de control y 48 torres", "Siete centros de control y 21 torres", "Cinco centros de control y 21 torres"]'::jsonb, 3, 'El tema indica que ENAIRE gestiona cinco centros de control y 21 torres (p. 4).', 'p. 4', 1, false),
  ('10000007-0000-4000-8002-000000000005', '00000000-0000-4000-8000-000000006007', '¿Qué superficie de espacio aéreo gestiona ENAIRE?', '["219.000 km²", "1.090.000 km²", "3.500.000 km²", "2.190.000 km²"]'::jsonb, 3, 'ENAIRE gestiona el espacio aéreo español, de 2.190.000 kilómetros cuadrados (p. 4).', 'p. 4', 2, false),
  ('10000007-0000-4000-8002-000000000006', '00000000-0000-4000-8000-000000006007', '¿En qué posición de Europa por volumen de tráfico se sitúa ENAIRE?', '["Primer proveedor", "Segundo proveedor", "Cuarto proveedor", "Décimo proveedor"]'::jsonb, 2, 'ENAIRE es el principal proveedor en España, el cuarto en Europa por volumen de tráfico (p. 4).', 'p. 4', 2, false),
  ('10000007-0000-4000-8002-000000000007', '00000000-0000-4000-8000-000000006007', '¿Cuántas personas transportó el tráfico atendido por ENAIRE en 2023?', '["Más de 28 millones", "Más de 100 millones", "Más de 328 millones", "Más de 2 millones"]'::jsonb, 2, 'El tráfico atendido (más de 2 millones de vuelos) transportó a más de 328 millones de personas en 2023 (p. 4).', 'p. 4', 2, false),
  ('10000007-0000-4000-8002-000000000008', '00000000-0000-4000-8000-000000006007', '¿En qué año fue designada ENAIRE Operador de Infraestructuras Críticas?', '["2014", "2015", "2019", "2004"]'::jsonb, 1, 'Fue designada Operador de Infraestructuras Críticas en 2015 y Operador de Servicios Esenciales en 2019 (p. 5).', 'p. 5', 2, false),
  ('10000007-0000-4000-8002-000000000009', '00000000-0000-4000-8000-000000006007', '¿Qué servicios de tránsito aéreo presta ENAIRE a través de sus centros y torres?', '["Control de área, aproximación y aeródromo, además de información de vuelo, alerta y asesoramiento", "Solo control de aeródromo", "Solo control de área y diseño de procedimientos", "Únicamente información de vuelo y servicios de alerta"]'::jsonb, 0, 'ENAIRE presta control de área, aproximación y aeródromo, así como información de vuelo, alerta y asesoramiento (pp. 4-5).', 'pp. 4-5', 2, false),
  ('10000007-0000-4000-8002-000000000010', '00000000-0000-4000-8000-000000006007', '¿Qué porcentaje de acciones de Aena S.A. posee ENAIRE?', '["El 36 %", "El 66,66 %", "El 100 %", "El 51 %"]'::jsonb, 3, 'ENAIRE es el accionista mayoritario de Aena S.A. con el 51 % de sus acciones (p. 7).', 'p. 7', 1, false),
  ('10000007-0000-4000-8002-000000000011', '00000000-0000-4000-8000-000000006007', '¿Qué participación tiene ENAIRE en CRIDA?', '["50 %", "45,85 %", "36 %", "66,66 %"]'::jsonb, 3, 'Entre sus participadas, CRIDA tiene el 66,66 % (p. 7).', 'p. 7', 2, false),
  ('10000007-0000-4000-8002-000000000012', '00000000-0000-4000-8000-000000006007', '¿Con qué empresa participada se asocia el porcentaje del 45,85 % de ENAIRE?', '["Ineco", "Startical", "CRIDA", "Grupo EAD"]'::jsonb, 0, 'ENAIRE posee el 45,85 % de Ineco; Startical 50 %, CRIDA 66,66 % y EAD 36 % (p. 7).', 'p. 7', 3, false),
  ('10000007-0000-4000-8002-000000000013', '00000000-0000-4000-8000-000000006007', '¿Qué participación tiene ENAIRE en el Grupo EAD?', '["36 %", "51 %", "50 %", "66,66 %"]'::jsonb, 0, 'Su participación en el Grupo EAD es del 36 % (p. 7).', 'p. 7', 3, false),
  ('10000007-0000-4000-8002-000000000014', '00000000-0000-4000-8000-000000006007', '¿Cuántas personas componen aproximadamente la plantilla de ENAIRE (octubre de 2024)?', '["Unas 2.000", "Más de 8.000", "Más de 4.200", "Alrededor de 1.200"]'::jsonb, 2, 'La plantilla supera las 4.200 personas, con datos a 31 de octubre de 2024 (p. 8).', 'p. 8', 1, false),
  ('10000007-0000-4000-8002-000000000015', '00000000-0000-4000-8000-000000006007', '¿Cuántos convenios colectivos diferenciados existen en ENAIRE?', '["Uno", "Tres", "Dos", "Cuatro"]'::jsonb, 2, 'Existen el III Convenio de Controladores de Tránsito Aéreo y el I Convenio del Grupo Aena para personal no controlador (p. 8).', 'p. 8', 1, false),
  ('10000007-0000-4000-8002-000000000016', '00000000-0000-4000-8000-000000006007', '¿Qué porcentaje aproximado de la plantilla son controladores aéreos?', '["Alrededor del 20 %", "Alrededor del 26 %", "Alrededor del 49 %", "Alrededor del 5 %"]'::jsonb, 2, 'Los controladores son alrededor del 49 % de la plantilla (p. 8).', 'p. 8', 2, false),
  ('10000007-0000-4000-8002-000000000017', '00000000-0000-4000-8000-000000006007', '¿Qué ocupación supone en torno al 20 % de la plantilla?', '["Operaciones", "Gestión", "Ingeniería y explotación técnica", "Controladores aéreos"]'::jsonb, 2, 'Ingeniería y Explotación Técnica supone sobre un 20 %; Operaciones un 5 % y Gestión un 26 % (p. 8).', 'p. 8', 2, false),
  ('10000007-0000-4000-8002-000000000018', '00000000-0000-4000-8000-000000006007', '¿Cómo se denomina el plan estratégico de ENAIRE para 2021-2025?', '["Cielo Único 2025", "Plan Director de Navegación Aérea", "Horizonte ENAIRE 2030", "Plan de Vuelo 2025"]'::jsonb, 3, 'El plan estratégico 2021-2025 es el Plan de Vuelo 2025, hoja de ruta de la transformación (pp. 3, 10).', 'pp. 3, 10', 1, false),
  ('10000007-0000-4000-8002-000000000019', '00000000-0000-4000-8000-000000006007', 'Según el propósito de ENAIRE, ¿cómo debe ser el vuelo que cuida?', '["Seguro, regular, económico y ordenado", "Puntual, barato, seguro y cómodo", "Seguro, competitivo, global e innovador", "Seguro, rápido, eficiente y sostenible"]'::jsonb, 3, 'El propósito es cuidar el vuelo para que sea seguro, rápido, eficiente y sostenible (p. 10).', 'p. 10', 2, false),
  ('10000007-0000-4000-8002-000000000020', '00000000-0000-4000-8000-000000006007', '¿Sobre qué tres pilares basa ENAIRE su visión de ser un operador global y líder?', '["Las personas, la innovación y la digitalización", "La seguridad, la capacidad y el medio ambiente", "Los clientes, los accionistas y los empleados", "La formación, la regularidad y el coste"]'::jsonb, 0, 'La visión se basa en las personas, la innovación y la digitalización (p. 10).', 'p. 10', 2, false),
  ('10000007-0000-4000-8002-000000000021', '00000000-0000-4000-8000-000000006007', '¿Qué incluye el primer objetivo estratégico del Plan de Vuelo 2025?', '["Impulsar la internacionalización del negocio", "Reforzar la seguridad, con atención a la cultura de seguridad, el factor humano y la ciberseguridad", "Contribuir a la movilidad sostenible y la descarbonización", "Asegurar la recuperación económica de ENAIRE"]'::jsonb, 1, 'El objetivo 1 es reforzar continuamente la seguridad, con atención a cultura de seguridad, factor humano y ciberseguridad (p. 10).', 'p. 10', 2, false),
  ('10000007-0000-4000-8002-000000000022', '00000000-0000-4000-8000-000000006007', '¿Cuál de estos es un objetivo estratégico del Plan de Vuelo 2025?', '["Contribuir a la movilidad sostenible minimizando el impacto ambiental e impulsando la descarbonización", "Privatizar los servicios de control de aeródromo", "Sustituir la formación OJT por simuladores", "Reducir la plantilla de controladores"]'::jsonb, 0, 'El objetivo 3 es contribuir a la movilidad sostenible, minimizando el impacto ambiental y impulsando la descarbonización (p. 11).', 'p. 11', 2, false),
  ('10000007-0000-4000-8002-000000000023', '00000000-0000-4000-8000-000000006007', '¿Qué persigue el objetivo estratégico 4 del Plan de Vuelo 2025?', '["La mejora de la ciberseguridad", "La digitalización de los servicios", "La recuperación económica y viabilidad", "El desarrollo de negocio y la internacionalización de ENAIRE"]'::jsonb, 3, 'El objetivo 4 es acometer el desarrollo del negocio y la internacionalización de ENAIRE (p. 11).', 'p. 11', 3, false),
  ('10000007-0000-4000-8002-000000000024', '00000000-0000-4000-8000-000000006007', '¿Quién creó la iniciativa del Cielo Único Europeo y en qué año?', '["La OACI, en 1944", "EUROCONTROL, en 1960", "La Comisión Europea, en 1999", "El Parlamento Europeo, en 2009"]'::jsonb, 2, 'La iniciativa SES fue creada por la Comisión Europea en 1999 (p. 11).', 'p. 11', 1, false),
  ('10000007-0000-4000-8002-000000000025', '00000000-0000-4000-8000-000000006007', '¿Cuál es uno de los dos objetivos principales del Cielo Único Europeo?', '["Unificar las licencias de los controladores", "Reducir la fragmentación del espacio aéreo europeo", "Eliminar los servicios militares del espacio aéreo", "Crear una única compañía aérea europea"]'::jsonb, 1, 'El SES busca mejorar la prestación de los servicios y reducir la fragmentación del espacio aéreo europeo (p. 11).', 'p. 11', 1, false),
  ('10000007-0000-4000-8002-000000000026', '00000000-0000-4000-8000-000000006007', '¿En qué años entraron en vigor los paquetes SES I y SES II?', '["SES I en 1999 y SES II en 2004", "SES I en 2004 y SES II en 2009", "SES I en 2009 y SES II en 2020", "SES I en 2000 y SES II en 2014"]'::jsonb, 1, 'Los paquetes SES I y SES II entraron en vigor en 2004 y 2009 respectivamente (p. 12).', 'p. 12', 2, false),
  ('10000007-0000-4000-8002-000000000027', '00000000-0000-4000-8000-000000006007', '¿En qué situación se encuentra la propuesta SES2+ según el tema?', '["Ya está aprobada y en vigor", "Ha sido retirada por la Comisión", "En negociación entre Comisión, Consejo y Parlamento Europeo (trílogos)", "Solo está pendiente de la ratificación de España"]'::jsonb, 2, 'La Comisión retomó SES2+ a finales de 2020 y está en proceso de negociación en trílogos (p. 12).', 'p. 12', 2, false),
  ('10000007-0000-4000-8002-000000000028', '00000000-0000-4000-8000-000000006007', '¿En qué áreas exige metas el sistema europeo de rendimientos?', '["Seguridad, formación, capacidad y puntualidad", "Seguridad, coste-eficiencia, capacidad y medioambiente", "Coste, tarifas, personal y medioambiente", "Capacidad, ciberseguridad, formación y coste"]'::jsonb, 1, 'El sistema requiere metas en cuatro áreas: seguridad, coste-eficiencia, capacidad y medioambiente, con incentivos y penalizaciones (p. 12).', 'p. 12', 2, false),
  ('10000007-0000-4000-8002-000000000029', '00000000-0000-4000-8000-000000006007', '¿Qué duración tienen los períodos de referencia del sistema de rendimientos?', '["Tres años siempre", "Cinco años (aunque el primero duró tres)", "Diez años", "Un año, renovable"]'::jsonb, 1, 'La normativa se despliega en períodos de cinco años, aunque el primero duró tres (p. 12).', 'p. 12', 2, false),
  ('10000007-0000-4000-8002-000000000030', '00000000-0000-4000-8000-000000006007', '¿Qué años abarca RP4?', '["2025-2029", "2020-2024", "2021-2025", "2030-2034"]'::jsonb, 0, 'RP4 abarca 2025-2029 y se prevén objetivos ambiciosos (p. 12).', 'p. 12', 2, false),
  ('10000007-0000-4000-8002-000000000031', '00000000-0000-4000-8000-000000006007', '¿Cuál de estas funciones corresponde al servicio ATS?', '["Diseñar procedimientos de vuelo", "Prevenir colisiones y acelerar y mantener ordenado el movimiento del tránsito aéreo", "Mantener las instalaciones de radioayudas", "Publicar la información aeronáutica para planificar"]'::jsonb, 1, 'El ATS previene colisiones, ordena el tránsito, da asesoramiento e información y notifica y auxilia en alerta y salvamento (p. 12).', 'p. 12', 1, false),
  ('10000007-0000-4000-8002-000000000032', '00000000-0000-4000-8000-000000006007', '¿Qué garantiza el servicio CNS?', '["La disponibilidad, explotación y mantenimiento de los medios técnicos e instalaciones del sistema de navegación aérea", "La coordinación civil/militar del espacio aéreo", "La regularidad de los vuelos y la capacidad", "La información para la planificación de operaciones"]'::jsonb, 0, 'El CNS (Comunicaciones, Navegación y Vigilancia) garantiza los medios técnicos e instalaciones en apoyo de la operación de aeronaves (p. 13).', 'p. 13', 2, false),
  ('10000007-0000-4000-8002-000000000033', '00000000-0000-4000-8000-000000006007', '¿Qué servicio pone a disposición de los usuarios la información del sistema de navegación aérea relevante para planificar sus operaciones?', '["ATFM", "ASM", "FPD", "AIS"]'::jsonb, 3, 'El AIS, Servicio de Información Aeronáutica, proporciona esa información actualizada y con calidad (p. 13).', 'p. 13', 1, false),
  ('10000007-0000-4000-8002-000000000034', '00000000-0000-4000-8000-000000006007', '¿Qué finalidad tiene la gestión de afluencia del tráfico aéreo (ATFM) según el tema?', '["Diseñar procedimientos de vuelo", "Coordinar civil y militar en nivel táctico", "Garantizar la regularidad de los vuelos y la capacidad en el espacio aéreo", "Mantener los sistemas de vigilancia"]'::jsonb, 2, 'El ATFM busca garantizar la regularidad de los vuelos y la capacidad en el espacio aéreo (p. 13).', 'p. 13', 2, false),
  ('10000007-0000-4000-8002-000000000035', '00000000-0000-4000-8000-000000006007', 'La ASM local que presta ENAIRE se desarrolla a nivel...', '["Estratégico (nivel 1)", "Pretáctico (nivel 2), solo para vuelos militares", "Táctico (nivel 3), asegurando la coordinación civil/militar", "Táctico (nivel 3), solo para vuelos comerciales"]'::jsonb, 2, 'ENAIRE presta ASM local (táctico/nivel 3) asegurando la coordinación entre civil y militar (p. 13).', 'p. 13', 3, false),
  ('10000007-0000-4000-8002-000000000036', '00000000-0000-4000-8000-000000006007', '¿Cuáles son las tres partes de la formación de unidad de un controlador?', '["Formación de transición (teoría), Pre-OJT (simulador) y OJT (puesto de trabajo)", "Teoría, examen y habilitación", "Actualización, conversión y lingüística", "Simulador, instructor y evaluación"]'::jsonb, 0, 'La formación de unidad consta de transición (teoría), Pre-OJT (simulador) y OJT (puesto de trabajo) (p. 14).', 'p. 14', 1, false),
  ('10000007-0000-4000-8002-000000000037', '00000000-0000-4000-8000-000000006007', '¿Qué permite ejercer la superación de la formación de unidad?', '["Ser instructor de la unidad", "Acceder a puestos de libre designación", "Obtener la certificación TRAINAIR PLUS", "Las atribuciones de la licencia en esa unidad"]'::jsonb, 3, 'Superada la formación de unidad, se pueden ejercer las atribuciones de la licencia en esa unidad (p. 14).', 'p. 14', 2, false),
